"""Synthetic English narration comparison; not a financial forecast or safety benchmark."""
import argparse
from datetime import datetime, timezone
from decimal import Decimal
import hashlib
import json
import os
from pathlib import Path
import re
import statistics
import time

import httpx
from pydantic import ValidationError

from copilot import TextNarration
from local_model_smoke import MAX_RESPONSE_BYTES, request_json


# Synthetic expected facts chosen by the fixture author, not generated by either tested model.
_ROWS = [
    ("stable", 45200, 12, 38000, 52000, 69000, 6, "Plan B"),
    ("income_drop", 18000, 64, -14000, 5000, 24000, 6, "Plan A"),
    ("zero_cash", 0, 90, -30000, -10000, 5000, 6, "Plan A"),
    ("zero_risk", 120000, 0, 100000, 150000, 200000, 6, "Status quo"),
    ("certain_shortfall", 1000, 100, -60000, -40000, -20000, 6, "Plan A"),
    ("decimal_values", 12345.67, 0.5, -100.75, 12345.67, 30000.25, 6, "Plan B"),
    ("one_month", 40000, 8, 30000, 40000, 50000, 1, "Status quo"),
    ("long_horizon", 65000, 35, -25000, 45000, 140000, 24, "Plan A"),
    ("equal_quantiles", 25000, 10, 25000, 25000, 25000, 6, "Plan B"),
    ("small_amounts", 10.25, 99.5, -5.5, 0, 20.75, 3, "Plan A"),
    ("large_amounts", 12345678, 2, 10000000, 15000000, 20000000, 12, "Status quo"),
    ("low_buffer", 37200, 24, 30000, 44000, 61000, 6, "Plan B"),
    ("all_zero", 0, 0, 0, 0, 0, 6, "Status quo"),
    ("signed_zero", -0.0, 0, -0.0, 0, 0, 1, "Status quo"),
    ("tiny_risk", 45200, 0.01, 38000, 52000, 69000, 6, "Plan B"),
    ("near_certain_risk", 100, 99.99, -10000, -5000, -1, 6, "Plan A"),
    ("one_paisa", 0.01, 50, -0.01, 0, 0.01, 1, "Plan A"),
    ("api_balance_limit", 1000000000000, 1, -1000000000000, 0, 1000000000000, 24, "Status quo"),
    ("nearly_equal_values", 100.01, 1.01, -100.01, -100, -99.99, 6, "Plan B"),
    ("zero_crossing", 1, 50, -1, 0, 1, 2, "Plan A"),
]
CASES = [dict(zip(("id", "bankCash", "riskPercent", "p10", "p50", "p90", "horizonMonths", "planId"), row))
         for row in _ROWS]
PROMPT = (
    "Restate supplied synthetic facts in English, using only ASCII and INR. Return JSON matching "
    "the schema. Each array has exactly one text item. Observed text must use labels: "
    "'Bank cash: INR <bankCash>; shortfall risk: <riskPercent>%.' Predicted text must use labels: "
    "'P10: INR <p10>; P50: INR <p50>; P90: INR <p90>; horizon: <horizonMonths> months.' "
    "Recommended text must name exactly the supplied planId and say 'requires simulation before "
    "commitment'. Do not calculate, invent additional numbers, judge adequacy, claim a plan benefit, "
    "suggest SIP changes, use tools or number lists. These are supplied forecasts, not guarantees. "
    "Schema: " + json.dumps(TextNarration.model_json_schema(), sort_keys=True)
)
NUMBER = r"[+-]?(?:\d{1,3}(?:,\d{3})+|\d{1,2}(?:,\d{2})+,\d{3}|\d+)(?:\.\d+)?"


class BenchmarkError(Exception):
    pass


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("Duplicate JSON key")
        result[key] = value
    return result


def score(case: dict, content: str) -> dict:
    result = {"schema_valid": False, "correct_facts": 0, "expected_facts": 7,
              "numbers_grounded": False, "case_pass": False, "failed_facts": []}
    try:
        narration = TextNarration.model_validate(json.loads(content, object_pairs_hook=_unique_object))
    except (ValueError, ValidationError, TypeError):
        return result
    result["schema_valid"] = True
    observed, predicted, recommended = (getattr(narration, key)[0].text
                                       for key in ("observed", "predicted", "recommended"))
    # Require a full monetary token, not a prefix of an exponent, fraction or scaled amount.
    money_end = r"(?=\s*(?:;|$|\.(?:\s|$)))"
    fields = [("bankCash", observed, r"Bank cash:\s*INR\s*", money_end),
              ("riskPercent", observed, r"shortfall risk:\s*", r"\s*%"),
              ("p10", predicted, r"P10:\s*INR\s*", money_end),
              ("p50", predicted, r"P50:\s*INR\s*", money_end),
              ("p90", predicted, r"P90:\s*INR\s*", money_end),
              ("horizonMonths", predicted, r"horizon:\s*", r"\s+months\b")]
    for key, text, prefix, suffix in fields:
        values = re.findall(prefix + "(" + NUMBER + ")" + suffix, text, flags=re.IGNORECASE)
        correct = len(values) == 1 and Decimal(values[0].replace(",", "")) == Decimal(str(case[key]))
        result["correct_facts"] += int(correct)
        if not correct:
            result["failed_facts"].append(key)
    plans = re.findall(r"\b(?:Plan [AB]|Status quo)\b", recommended)
    plan_ok = plans == [case["planId"]]
    result["correct_facts"] += int(plan_ok)
    if not plan_ok:
        result["failed_facts"].append("planId")
    text = " ".join((observed, predicted, recommended))
    text = re.sub(r"\bP(?:10|50|90)\b", "", text, flags=re.IGNORECASE)
    allowed = {Decimal(str(case[key])) for key, *_ in fields}
    numbers = re.findall(NUMBER, text)
    result["numbers_grounded"] = all(Decimal(n.replace(",", "")) in allowed for n in numbers)
    result["case_pass"] = (result["correct_facts"] == 7 and result["numbers_grounded"] and
                           "requires simulation before commitment" in recommended.lower())
    return result


def generate(provider: str, model: str, case: dict, timeout: int) -> str:
    messages = [{"role": "system", "content": PROMPT},
                {"role": "user", "content": json.dumps({k: v for k, v in case.items() if k != "id"})}]
    if provider == "groq":
        key = os.getenv("GROQ_API_KEY", "").strip()
        if not key:
            raise BenchmarkError("MISSING_KEY")
        url = "https://api.groq.com/openai/v1/chat/completions"
        headers = {"Authorization": "Bearer " + key}
        payload = {"model": model, "messages": messages, "temperature": 0,
                   "response_format": {"type": "json_object"}, "max_completion_tokens": 1536}
        if model.startswith("openai/gpt-oss-"):
            payload["reasoning_effort"] = "low"
    elif provider == "ollama":
        url, headers = "http://127.0.0.1:11434/api/chat", {}
        payload = {"model": model, "messages": messages, "stream": False, "think": False,
                   "format": "json", "keep_alive": "2m",
                   "options": {"temperature": 0, "num_ctx": 2048, "num_predict": 384}}
    else:
        raise BenchmarkError("INVALID_PROVIDER")
    try:
        with httpx.Client(timeout=timeout, trust_env=False, follow_redirects=False) as client:
            with client.stream("POST", url, json=payload, headers=headers) as response:
                if response.status_code != 200:
                    raise BenchmarkError("HTTP_" + str(response.status_code))
                body = bytearray()
                for chunk in response.iter_bytes(chunk_size=8192):
                    body.extend(chunk)
                    if len(body) > MAX_RESPONSE_BYTES:
                        raise BenchmarkError("OVERSIZED_RESPONSE")
        data = json.loads(body)
        if provider == "ollama":
            if data.get("done") is not True or data.get("done_reason") not in (None, "stop"):
                raise BenchmarkError("INCOMPLETE_GENERATION")
            content = data["message"]["content"]
        else:
            choice = data["choices"][0]
            if choice.get("finish_reason") != "stop":
                raise BenchmarkError("INCOMPLETE_GENERATION")
            content = choice["message"]["content"]
        if not isinstance(content, str):
            raise BenchmarkError("INVALID_RESPONSE")
        return content
    except httpx.TimeoutException:
        raise BenchmarkError("TIMEOUT") from None
    except httpx.HTTPError:
        raise BenchmarkError("CONNECTION_ERROR") from None
    except (ValueError, TypeError, KeyError, IndexError, AttributeError):
        raise BenchmarkError("INVALID_RESPONSE") from None


def failed_result(reason: str, elapsed: float) -> dict:
    return {"status": reason, "elapsed_seconds": round(elapsed, 3), "schema_valid": False,
            "correct_facts": 0, "expected_facts": 7, "numbers_grounded": False, "case_pass": False}


def summarize(results: list[dict]) -> dict:
    count = len(results)
    return {"attempted_cases": count, "expected_facts": count * 7,
            "fact_accuracy_percent": round(100 * sum(r["correct_facts"] for r in results) / (count * 7), 2) if count else None,
            "schema_valid_percent": round(100 * sum(r["schema_valid"] for r in results) / count, 2) if count else None,
            "case_pass_percent": round(100 * sum(r["case_pass"] for r in results) / count, 2) if count else None,
            "numeric_grounding_percent": round(100 * sum(r["numbers_grounded"] for r in results) / count, 2) if count else None,
            "median_attempt_seconds": round(statistics.median(r["elapsed_seconds"] for r in results), 3) if count else None,
            "request_failures": sum(r["status"] != "OK" for r in results)}


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--providers", choices=("both", "ollama", "groq"), default="both")
    parser.add_argument("--ollama-model", default="qwen2.5-coder:7b")
    parser.add_argument("--groq-model", default="openai/gpt-oss-20b")
    parser.add_argument("--limit", type=int, default=len(CASES))
    parser.add_argument("--repeats", type=int, default=1)
    parser.add_argument("--timeout", type=int, default=90)
    args = parser.parse_args()
    if not (1 <= args.limit <= len(CASES) and 1 <= args.repeats <= 3 and 1 <= args.timeout <= 300):
        parser.error(f"limit 1..{len(CASES)}, repeats 1..3 and timeout 1..300 required")
    for model in (args.ollama_model, args.groq_model):
        if not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_./:-]{0,100}", model) or "cloud" in model.lower():
            parser.error("Use a valid model id; cloud-backed Ollama models are disabled")
    report = {"scope": "Exploratory synthetic English fact-preservation, NOT general model accuracy or forecast accuracy",
              "production_number_verifier": "NOT_RUN", "semantic_safety": "HUMAN_REVIEW_REQUIRED",
              "prompt_sha256": hashlib.sha256(PROMPT.encode()).hexdigest(), "prompt": PROMPT,
              "cases": CASES[:args.limit], "repeats": args.repeats, "providers": {}}
    providers = ("ollama", "groq") if args.providers == "both" else (args.providers,)
    incomplete = False
    for provider in providers:
        model = args.ollama_model if provider == "ollama" else args.groq_model
        entry = {"model": model, "planned_cases": args.limit * args.repeats, "results": []}
        report["providers"][provider] = entry
        try:
            if provider == "groq" and not os.getenv("GROQ_API_KEY", "").strip():
                raise BenchmarkError("MISSING_KEY_RUN_IN_YOUR_AUTHENTICATED_TERMINAL")
            if provider == "ollama":
                metadata = request_json("/api/show", {"model": model}, 10)
                if metadata.get("remote_host") or metadata.get("remote_model"):
                    raise BenchmarkError("REMOTE_OLLAMA_MODEL_DISABLED")
                entry["model_digest_note"] = "Installed model metadata; preserve tag/version for reproducibility"
                entry["model_details"] = metadata.get("details", {})
        except Exception as error:
            entry["status"] = str(error) if isinstance(error, BenchmarkError) else "LOCAL_PREFLIGHT_FAILED"
            entry["summary"] = summarize([])
            print(provider + ": NOT RUN (" + entry["status"] + ")", flush=True)
            incomplete = True
            continue
        entry["status"] = "COMPLETED"
        for repeat in range(args.repeats):
            for case in CASES[:args.limit]:
                started = time.perf_counter()
                try:
                    content = generate(provider, model, case, args.timeout)
                    result = score(case, content) | {"status": "OK", "elapsed_seconds": round(time.perf_counter() - started, 3),
                                                    "output": content}
                except BenchmarkError as error:
                    result = failed_result(str(error), time.perf_counter() - started)
                result.update(case_id=case["id"], repeat=repeat + 1)
                entry["results"].append(result)
                print(f"{provider} {case['id']}: {result['correct_facts']}/7 facts, pass={result['case_pass']}, "
                      f"status={result['status']}, {result['elapsed_seconds']}s", flush=True)
                # No retry storm or further requests after quota/auth/billing failure.
                if result["status"] in {"HTTP_401", "HTTP_402", "HTTP_403", "HTTP_429"}:
                    entry["status"] = "STOPPED_" + result["status"]
                    incomplete = True
                    break
            if entry["status"] != "COMPLETED":
                break
        entry["summary"] = summarize(entry["results"])
        print(provider + " summary: " + json.dumps(entry["summary"]), flush=True)
    output_dir = Path(__file__).parent / "build" / "model-evaluation"
    output_dir.mkdir(parents=True, exist_ok=True)
    path = output_dir / (datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S%fZ") + ".json")
    path.write_text(json.dumps(report, ensure_ascii=True, indent=2), encoding="utf-8")
    print("Report: " + str(path.resolve()))
    return 2 if incomplete else 0


if __name__ == "__main__":
    raise SystemExit(main())
